    const key = (kind: SearchSubjectKind, id: string) => `${kind}:${id}`;

    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
      });

      for (const project of projects.items) {
        live.add(key("project", project.id));
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      projectCursor = projects.nextCursor;
    } while (projectCursor !== null);

    // Archived issues and deleted comments are left out: they must not be
    // findable. A live reply is indexed even when its parent was deleted.
    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
      });

      for (const issue of issues.items) {
        live.add(key("issue", issue.id));
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }

        let commentCursor: string | null = null;
        do {
          const comments = await commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: false,
            limit: PAGE_SIZE,
            cursor: commentCursor,
          });

          for (const comment of comments.items) {
            live.add(key("comment", comment.id));
            try {
              await indexComment(orgId, comment);
              result.processed += 1;
            } catch (error) {
              result.failed += 1;
              logger.error("failed to index comment", {
                commentId: comment.id,
                reason: error instanceof Error ? error.message : String(error),
              });
            }
          }

          commentCursor = comments.nextCursor;
        } while (commentCursor !== null);
      }

      issueCursor = issues.nextCursor;
    } while (issueCursor !== null);

    const stale = new Map<SearchSubjectKind, string[]>();
    for (const doc of await searchRepo.listIndexedSubjects(orgId)) {
      if (live.has(key(doc.subjectKind, doc.subjectId))) continue;
      const bucket = stale.get(doc.subjectKind) ?? [];
      bucket.push(doc.subjectId);
      stale.set(doc.subjectKind, bucket);
    }
    for (const [kind, ids] of stale) {
      await searchRepo.deleteSearchDocuments(orgId, kind, ids);
    }
  });
}
